parameters.jsCode:
const gerado = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const o = $('Ofertas pendentes').item.json;

let linkAfiliado = o.link_afiliado || o.link_original;
if (o.fonte === 'amazon' && !o.link_afiliado) {
  linkAfiliado = o.link_original.includes('?')
    ? `${o.link_original}&tag=${$env.AMAZON_PARTNER_TAG}`
    : `${o.link_original}?tag=${$env.AMAZON_PARTNER_TAG}`;
}

return { json: { ...o, textoGerado: gerado, linkAfiliado } };

const kuttResp = $input.item.json;
const oferta = $('Prepara Link Afiliado').item.json;

const kuttShortUrl = kuttResp.link || kuttResp.short_url || oferta.linkAfiliado;
const kuttLinkId = kuttResp.address || kuttResp.id || null;

const postFinal = `${oferta.textoGerado}\n\n🔗 ${kuttShortUrl}\n\n#oferta #${oferta.fonte}`;

return {
  json: {
    ...oferta,
    kuttShortUrl,
    kuttLinkId,
    postFinal
  }
};
